/* Load editor modules only after updating an older project service worker. */
const EXPECTED='field-signal-game-first-release-11-1';
async function current(){const worker=navigator.serviceWorker?.controller;if(!worker)return false;return new Promise(resolve=>{const c=new MessageChannel(),timer=setTimeout(()=>{c.port1.close();resolve(false)},1000);c.port1.onmessage=e=>{clearTimeout(timer);c.port1.close();resolve(e.data?.cache===EXPECTED)};worker.postMessage({type:'editor-version'},[c.port2]);});}
async function start(){try{if('serviceWorker'in navigator&&isSecureContext){if(!await current()){const r=await navigator.serviceWorker.register(new URL('./sw.js',document.baseURI),{scope:new URL('./',document.baseURI).pathname,updateViaCache:'none'});await r.update();let ok=false;for(let i=0;i<12;i++){if(await current()){ok=true;break;}await new Promise(r=>setTimeout(r,300));}if(!ok&&navigator.serviceWorker.controller)throw Error('The installed offline runtime could not update. Reconnect and refresh. Your campaign and drafts have not been changed.');}}await import('./editor.js');}catch(e){document.querySelector('#loading strong').textContent='Editor needs a fresh runtime';document.querySelector('#loading span').textContent=e.message;document.querySelector('#save-state').textContent='No saved data was changed';console.error(e);}}
start();
